def shannon_entropy(p):
    import math
    return -sum(pi * math.log(pi) for pi in p if pi > 0)

def entropy_power(p, d=1):
    import math
    h = shannon_entropy(p)
    return math.exp(2 * h / d)

def discrete_convolution(p, q):
    m, n = len(p), len(q)
    result = [0.0] * (m + n - 1)
    for i in range(m):
        for j in range(n):
            result[i + j] += p[i] * q[j]
    return result
